  END substring;

  FUNCTION is_blank(p_s IN VARCHAR2) RETURN BOOLEAN IS
  BEGIN
    RETURN ((p_s IS NULL OR LENGTH(p_s) = 0) OR (trim_ws(p_s) IS NULL OR LENGTH(trim_ws(p_s)) = 0));
  END is_blank;

  FUNCTION has(p_haystack IN VARCHAR2, p_needle IN VARCHAR2) RETURN BOOLEAN IS
  BEGIN
